import * as rental from "host/rental";
import * as organizer from "host/organizer";
import * as strings from "std/string";

function decimal(value: int): string {
    let result: string = "";
    let remaining: int = value;
    if (remaining === 0) {
        return "0";
    }
    while (remaining > 0) {
        let digit: int = remaining % 10;
        result = strings.substring("0123456789", digit, digit + 1) + result;
        remaining = remaining / 10;
    }
    return result;
}

function euroTotal(cents: int): string {
    let whole: int = cents / 100;
    let fraction: int = cents % 100;
    let fractionText: string = decimal(fraction);
    if (fraction < 10) {
        fractionText = "0" + fractionText;
    }
    return "€" + decimal(whole) + "." + fractionText + " total";
}

function asciiLower(text: string): string {
    let upper: string = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    let lower: string = "abcdefghijklmnopqrstuvwxyz";
    let result: string = "";
    for (let scalar: string of text) {
        let replacement: string = scalar;
        let index: int = 0;
        while (index < 26) {
            if (scalar === strings.substring(upper, index, index + 1)) {
                replacement = strings.substring(lower, index, index + 1);
            }
            index = index + 1;
        }
        result = result + replacement;
    }
    return result;
}

function buildState(quantity: int, budgetCents: int, search: string, sourceRows: RentalOption[], selectedId: string | null, loading: boolean, preparing: boolean, loaded: boolean, prepared: boolean, error: string, retryPrepare: boolean): State {
    let quantityError: string = "";
    let budgetError: string = "";
    if (quantity < 1 || quantity > 8) {
        quantityError = "Quantity must be between 1 and 8.";
    }
    if (budgetCents < 0 || budgetCents > 100000) {
        budgetError = "Total budget must be between 0 and 100000 cents.";
    }
    let editable: boolean = !loading && !preparing;
    let valid: boolean = quantityError === "" && budgetError === "";
    let rows: RentalOption[] = [];
    let hasSelection: boolean = false;
    for (let row: RentalOption of sourceRows) {
        let selected: boolean = false;
        if (selectedId !== null) {
            selected = selectedId === row.id;
        }
        if (selected) {
            hasSelection = true;
        }
        let copy: RentalOption = {
            id: row.id,
            title: row.title,
            detail: row.detail,
            totalCents: row.totalCents,
            price: row.price,
            meta: row.meta,
            selected: selected,
            enabled: editable
        };
        rows[rows.length] = copy;
    }
    let retainedId: string | null = null;
    if (hasSelection) {
        retainedId = selectedId;
    }
    return {
        quantity: quantity,
        budgetCents: budgetCents,
        search: search,
        periodStart: "2026-10-10T16:00:00Z",
        periodEnd: "2026-10-10T22:00:00Z",
        quantityError: quantityError,
        budgetError: budgetError,
        rows: rows,
        selectedId: retainedId,
        loading: loading,
        preparing: preparing,
        loaded: loaded,
        prepared: prepared && hasSelection,
        error: error,
        retryPrepare: retryPrepare,
        editable: editable,
        canLoad: valid && editable,
        canPrepare: valid && editable && hasSelection,
        empty: loaded && rows.length === 0 && error === "" && editable
    };
}

function unchanged(state: State): State {
    return buildState(state.quantity, state.budgetCents, state.search, state.rows, state.selectedId, state.loading, state.preparing, state.loaded, state.prepared, state.error, state.retryPrepare);
}

export function main(): null {
    return null;
}

export function initialState(): State {
    return {};
}

// @ui-update
export function changeQuantity(state: State, action: ChangeQuantity): State {
    if (!state.editable) {
        return unchanged(state);
    }
    return buildState(action.value, state.budgetCents, state.search, [], null, false, false, false, false, "", false);
}

// @ui-update
export function changeBudget(state: State, action: ChangeBudget): State {
    if (!state.editable) {
        return unchanged(state);
    }
    return buildState(state.quantity, action.value, state.search, [], null, false, false, false, false, "", false);
}

// @ui-update
export function changeSearch(state: State, action: ChangeSearch): State {
    if (!state.editable) {
        return unchanged(state);
    }
    return buildState(state.quantity, state.budgetCents, action.value, [], null, false, false, false, false, "", false);
}

// @ui-update
export function requestOptions(state: State, action: LoadOptions): State {
    if (!state.canLoad) {
        return unchanged(state);
    }
    return buildState(state.quantity, state.budgetCents, state.search, [], null, true, false, false, false, "", false);
}

// @ui-effect
export async function loadOptions(state: State, action: LoadOptions): OptionsLoaded {
    if (state.quantity < 1 || state.quantity > 8 || state.budgetCents < 0 || state.budgetCents > 100000 || state.preparing) {
        return { rows: [], error: "Cannot load options: check quantity and total budget." };
    }
    try {
        let records: table[] = await rental.equipment(state.periodStart, state.periodEnd);
        let rows: RentalOption[] = [];
        let query: string = asciiLower(strings.trim(state.search));
        for (let record: table of records) {
            let id: string = record.id;
            let title: string = record.name;
            let specification: string = record.specification;
            let cents: int = record.cents;
            let available: int = record.available;
            let searchable: string = asciiLower(title + " " + specification);
            let matchesRequirement: boolean = strings.contains(searchable, "boom") && strings.contains(searchable, "stand");
            let matchesSearch: boolean = query === "" || strings.contains(searchable, query);
            if (matchesRequirement && matchesSearch && available >= state.quantity && cents >= 0) {
                if (cents <= state.budgetCents / state.quantity) {
                    let totalCents: int = cents * state.quantity;
                    let row: RentalOption = {
                        id: id,
                        title: title,
                        detail: specification,
                        totalCents: totalCents,
                        price: euroTotal(totalCents),
                        meta: "Total for " + decimal(state.quantity) + " unit(s); available: " + decimal(available),
                        selected: false,
                        enabled: true
                    };
                    rows[rows.length] = row;
                }
            }
        }
        return { rows: rows, error: "" };
    } catch (e) {
        return { rows: [], error: "Rental catalogue capability failed: " + e.message };
    }
}

// @ui-update
export function receiveOptions(state: State, action: OptionsLoaded): State {
    return buildState(state.quantity, state.budgetCents, state.search, action.rows, null, false, false, true, false, action.error, false);
}

// @ui-update
export function pickOption(state: State, action: PickOption): State {
    if (!state.editable) {
        return unchanged(state);
    }
    return buildState(state.quantity, state.budgetCents, state.search, state.rows, action.value, false, false, state.loaded, false, "", false);
}

// @ui-update
export function requestPreparation(state: State, action: PrepareForReview): State {
    if (!state.canPrepare) {
        return unchanged(state);
    }
    return buildState(state.quantity, state.budgetCents, state.search, state.rows, state.selectedId, false, true, state.loaded, false, "", true);
}

// @ui-effect
export async function prepareForReview(state: State, action: PrepareForReview): PreparationFinished {
    let selectedId: string | null = state.selectedId;
    if (selectedId === null || state.quantity < 1 || state.quantity > 8 || state.budgetCents < 0 || state.budgetCents > 100000 || state.loading) {
        return { prepared: false, error: "Cannot prepare: select a qualifying option with valid inputs." };
    }
    try {
        for (let row: RentalOption of state.rows) {
            let currentId: string | null = state.selectedId;
            if (currentId !== null) {
                if (row.id === currentId) {
                    let detail: string = "Item " + row.id + ":" + decimal(state.quantity) + "; from " + state.periodStart + "; until " + state.periodEnd;
                    let result: table = await organizer.stage("rental", "host/rental", row.title, detail, euroTotal(row.totalCents), state.periodEnd);
                    let staged: boolean = result.staged;
                    if (!staged) {
                        return { prepared: false, error: "Local preparation capability did not prepare the descriptor. Retry to prepare for native review." };
                    }
                    return { prepared: true, error: "" };
                }
            }
        }
        return { prepared: false, error: "Cannot prepare: the selected option is no longer in the shortlist." };
    } catch (e) {
        return { prepared: false, error: "Local preparation capability failed: " + e.message };
    }
}

// @ui-update
export function receivePreparation(state: State, action: PreparationFinished): State {
    return buildState(state.quantity, state.budgetCents, state.search, state.rows, state.selectedId, false, false, state.loaded, action.prepared, action.error, true);
}

export class RentalOption {
    id: string = "";
    title: string = "";
    detail: string = "";
    totalCents: int = 0;
    price: string = "";
    meta: string = "";
    selected: boolean = false;
    enabled: boolean = true;
}

export class State {
    quantity: int = 1;
    budgetCents: int = 2000;
    search: string = "";
    periodStart: string = "2026-10-10T16:00:00Z";
    periodEnd: string = "2026-10-10T22:00:00Z";
    quantityError: string = "";
    budgetError: string = "";
    rows: RentalOption[] = [];
    selectedId: string | null = null;
    loading: boolean = false;
    preparing: boolean = false;
    loaded: boolean = false;
    prepared: boolean = false;
    error: string = "";
    retryPrepare: boolean = false;
    editable: boolean = true;
    canLoad: boolean = true;
    canPrepare: boolean = false;
    empty: boolean = false;
}

export class ChangeQuantity {
    value: int = 1;
}

export class ChangeBudget {
    value: int = 2000;
}

export class ChangeSearch {
    value: string = "";
}

export class LoadOptions {}

export class OptionsLoaded {
    rows: RentalOption[] = [];
    error: string = "";
}

export class PickOption {
    value: string = "";
}

export class PrepareForReview {}

export class PreparationFinished {
    prepared: boolean = false;
    error: string = "";
}

