import * as app from "./experience";
import * as ui from "./platform.dealui-pack";
// @ui-root
export view RentalShortlist(state: app.State): View {
    ui.Column() {
        ui.Text(value: "Rental shortlist")
        ui.Text(value: "Boom stand · Adjustable boom")
        ui.Text(value: "Change quantity and total budget to refine your shortlist. The default 1 unit / 2000 cents includes qualifying stand and package options when available.")
        ui.Card() {
            ui.IntField(value: state.quantity, label: "Quantity", minimum: 0, maximum: 9, step: 1, enabled: state.editable, supporting: "Choose 1 to 8 units. Changing quantity clears options and preparation.", error: state.quantityError, onChange: action app.ChangeQuantity { value: payload }, accessibilityLabel: "Quantity")
            ui.IntField(value: state.budgetCents, label: "Total budget in cents", minimum: 0, maximum: 100000, step: 100, enabled: state.editable, supporting: "Budget for all units, not per unit. Changing the budget clears options and preparation.", error: state.budgetError, onChange: action app.ChangeBudget { value: payload }, accessibilityLabel: "Budget")
            ui.SearchField(value: state.search, label: "Search", multiline: false, enabled: state.editable, supporting: "Optional name or specification substring. Changing search clears options and preparation.", error: "", onChange: action app.ChangeSearch { value: payload }, accessibilityLabel: "Search")
            ui.Text(value: "Rental period")
            ui.Text(value: state.periodStart)
            ui.Text(value: state.periodEnd)
            ui.Button(text: "Load options", enabled: state.canLoad, onClick: action app.LoadOptions {}, accessibilityLabel: "Load options")
        }
        When(state.loading) {
            ui.Progress(label: "Loading")
        }
        When(state.preparing) {
            ui.Progress(label: "Preparing for native review")
        }
        When(state.error !== "") {
            When(state.retryPrepare) {
                ui.Failure(text: state.error, onRetry: action app.PrepareForReview {}, accessibilityLabel: "Retry preparation for native review")
            } Else {
                ui.Failure(text: state.error, onRetry: action app.LoadOptions {}, accessibilityLabel: "Retry loading rental options")
            }
        }
        When(state.empty) {
            ui.Text(value: "No qualifying options")
            ui.Text(value: "Try lowering quantity, increasing the total budget, or clearing Search, then load options again.")
        }
        ui.Section(title: "Qualifying options", summary: "Each price is the total for your quantity. Only available equipment matching both boom and stand is shown.") {
            ForEach(state.rows, row: app.RentalOption, key: row.id) {
                ui.Option(value: row.id, title: row.title, detail: row.detail, price: row.price, meta: row.meta, selected: row.selected, enabled: row.enabled, onSelect: action app.PickOption { value: payload }, accessibilityLabel: row.title)
            }
            ui.Button(text: "Prepare for review", enabled: state.canPrepare, onClick: action app.PrepareForReview {}, accessibilityLabel: "Prepare for review")
        }
        When(state.prepared) {
            ui.Notice(text: "Prepared for native review", tone: "info")
        }
        ui.Text(value: "Preparation is local only. Nothing is reserved or confirmed; native review and confirmation happen outside this shortlist.")
    }
}
